// Pure helpers for code-mode: the runner's wire protocol, result shaping,
// tool search and type extraction. No `$` here, so tests can call them directly.

export const MARK = '\u0001cm '

export type RunnerCall = { t: 'call'; id: number; tool: string; args: Record<string, unknown> }
export type RunnerRecall = { t: 'recall'; id: number; ref: number }
export type RunnerSave = { t: 'save'; id: number; name: string; data: unknown }
export type RunnerRead = { t: 'read'; id: number; path: string }
export type RunnerResources = { t: 'resources'; id: number; server?: string }
export type RunnerResource = { t: 'resource'; id: number; server: string; uri: string }
export type RunnerDone = { t: 'done'; value: string; logs: string[] }
export type RunnerError = { t: 'error'; message: string; logs: string[] }
export type RunnerMessage =
  | RunnerCall
  | RunnerRecall
  | RunnerSave
  | RunnerRead
  | RunnerResources
  | RunnerResource
  | RunnerDone
  | RunnerError

// Each kind of message, with the fields the host reads and their types. The
// `satisfies` makes the table list every kind of RunnerMessage and no other.
// runner.integration.mjs checks that the runner sends these kinds.
const RUNNER_FIELDS = {
  call: { id: 'number', tool: 'string' },
  recall: { id: 'number', ref: 'number' },
  save: { id: 'number', name: 'string' },
  read: { id: 'number', path: 'string' },
  resources: { id: 'number' },
  resource: { id: 'number', server: 'string', uri: 'string' },
  done: { value: 'string', logs: 'array' },
  error: { message: 'string', logs: 'array' },
} as const satisfies Record<RunnerMessage['t'], Record<string, 'number' | 'string' | 'array'>>

/** The message in one protocol line, or undefined when it is not a known kind with the fields of that kind. */
const parseRunnerMessage = (text: string): RunnerMessage | undefined => {
  let m: unknown
  try {
    m = JSON.parse(text)
  } catch {
    return undefined
  }
  if (typeof m !== 'object' || m === null) return undefined
  const t = (m as { t?: unknown }).t
  if (typeof t !== 'string' || !Object.hasOwn(RUNNER_FIELDS, t)) return undefined
  const fields: Record<string, string> = RUNNER_FIELDS[t as RunnerMessage['t']]
  for (const [name, type] of Object.entries(fields)) {
    const v = (m as Record<string, unknown>)[name]
    if (type === 'array' ? !Array.isArray(v) : typeof v !== type) return undefined
  }
  return m as RunnerMessage
}

export type Reply = { ok: true; value: unknown } | { ok: false; error: string }

export type ToolEntry = { name: string; description: string }

/** Splits buffered stdout into whole protocol lines; other lines are ignored. */
export const takeMessages = (buffer: string): { messages: RunnerMessage[]; rest: string } => {
  const messages: RunnerMessage[] = []
  let rest = buffer
  let i = rest.indexOf('\n')
  while (i >= 0) {
    const line = rest.slice(0, i)
    rest = rest.slice(i + 1)
    // a line that is not a message is the script's own output, not ours
    const m = line.startsWith(MARK) ? parseRunnerMessage(line.slice(MARK.length)) : undefined
    if (m) messages.push(m)
    i = rest.indexOf('\n')
  }
  return { messages, rest }
}

/** The message of a thrown value. */
export const errorText = (err: unknown): string => (err instanceof Error ? err.message : String(err))

/** True for a tool the sandbox may call: any MCP tool except this plugin's own. */
export const isCallable = (tool: string, plugin: string): tool is `mcp__${string}__${string}` =>
  tool.startsWith('mcp__') && !tool.startsWith(`mcp__${plugin}__`)

/** `mcp__<server>__<tool>` as the server and the tool's name on it. */
export const splitToolName = (tool: string): { server: string; name: string } | undefined => {
  const rest = tool.startsWith('mcp__') ? tool.slice('mcp__'.length) : ''
  const at = rest.indexOf('__')
  if (at <= 0 || at + 2 >= rest.length) return undefined
  return { server: rest.slice(0, at), name: rest.slice(at + 2) }
}

type McpResultLike = {
  content: readonly { type: string; text?: unknown }[]
  isError: boolean
  structuredContent?: unknown
}

/** The reply for a `$.mcp.call` result: its text blocks joined, as the model would read them. */
export const mcpReply = (r: McpResultLike): Reply => {
  const text = r.content
    .map(block => (block.type === 'text' && typeof block.text === 'string' ? block.text : `[${block.type} block]`))
    .join('\n')
  if (r.isError) return { ok: false, error: text || 'the tool reported an error' }
  return { ok: true, value: toValue({ structuredContent: r.structuredContent }, text) }
}

/** What the script receives for a tool result: structured data when there is any. */
export const toValue = (result: unknown, text: string | undefined): unknown => {
  if (result !== null && typeof result === 'object' && 'structuredContent' in result) {
    const structured = (result as { structuredContent?: unknown }).structuredContent
    if (structured !== undefined) return structured
  }
  const raw = text ?? (typeof result === 'string' ? result : undefined)
  if (raw === undefined) return result ?? null
  try {
    return JSON.parse(raw)
  } catch {
    return raw
  }
}

/**
 * A tool result Claude Code saved to a file because it was too large: the
 * model would read only a note with the path, so the program gets the file.
 * `format` is how the file holds the result, when the note says; `isCut`
 * when the note says the file holds part of it.
 */
export type SavedResult = { path: string; format: 'text' | 'json' | 'blocks' | 'unknown'; isCut: boolean }

// Claude Code's notes as of 2.1.295: the MCP one ("Format: Plain text", "JSON
// with schema: …", "JSON array …") and the one for any tool's output. They
// give the format and a path with spaces. A note in another wording is found
// by the path alone: a path in this session's tool-results/ folder.
const MCP_SAVED =
  /^Error: result \([^)]*\) exceeds maximum allowed tokens\. Output has been saved to (.+)\.\nFormat: ([^\n]*)/
const OUTPUT_SAVED = /^<persisted-output>\n[^\n]*?(?:Full output saved to|were saved to): ([^\n]+)/
const CUT = /exceeded the persist byte limit|only the first [^\n]* were saved to/
const PATH = /\/[^\s"'`<>()]+/g
// A note is short; a longer result that names a path is the tool's own data.
const MAX_NOTE_CHARS = 8_000

/** The saved result a tool's text names, or undefined for an ordinary result. */
export const savedResultOf = (text: string, sessionId: string): SavedResult | undefined => {
  if (sessionId === '' || text.length > MAX_NOTE_CHARS) return undefined
  const isCut = CUT.test(text)
  const mcp = MCP_SAVED.exec(text)
  if (mcp && isSessionResult(mcp[1]!, sessionId)) {
    const format = mcp[2]!.startsWith('JSON array') ? 'blocks' : mcp[2]!.startsWith('JSON') ? 'json' : 'text'
    return { path: mcp[1]!, format, isCut }
  }
  const output = OUTPUT_SAVED.exec(text)
  if (output && isSessionResult(output[1]!.trim(), sessionId)) return { path: output[1]!.trim(), format: 'text', isCut }
  const paths = new Set(
    [...text.matchAll(PATH)].map(m => m[0].replace(/[.,;:!?\]]+$/, '')).filter(p => isSessionResult(p, sessionId)),
  )
  return paths.size === 1 ? { path: [...paths][0]!, format: 'unknown', isCut } : undefined
}

/** True when a path is a file in this session's `tool-results/` folder. */
export const isSessionResult = (path: string, sessionId: string): boolean => {
  const parts = path.split('/')
  return sessionId !== '' && parts.at(-2) === 'tool-results' && parts.includes(sessionId) && !parts.includes('..')
}

const CONTENT_TYPES = new Set(['text', 'image', 'audio', 'resource', 'resource_link', 'document'])

// MCP content blocks, not data that has a `type` field of its own.
const isBlocks = (v: unknown): v is McpResultLike['content'] =>
  Array.isArray(v) &&
  v.some(b => b?.type === 'text') &&
  v.every(b => b !== null && typeof b === 'object' && CONTENT_TYPES.has((b as { type?: unknown }).type as string))

/** The reply for a saved result, read back from its file. */
export const savedReply = (format: SavedResult['format'], fileText: string): Reply => {
  if (format === 'text') return { ok: true, value: toValue(undefined, fileText) }
  let parsed: unknown
  try {
    parsed = JSON.parse(fileText)
  } catch {
    // JSON that does not parse was cut; text that is not JSON is the result.
    if (format === 'unknown') return { ok: true, value: fileText }
    return { ok: false, error: 'the saved result is not whole' }
  }
  if (format === 'json' || !isBlocks(parsed)) return { ok: true, value: parsed }
  // Content blocks: joined as the model would read them, like a live result.
  return mcpReply({ content: parsed, isError: false })
}

const clip = (text: string, max: number, whole?: number): string => {
  if (text.length <= max) return text
  const fix =
    whole === undefined ? 'return less data' : `await recall(${whole}) returns the whole result: return a part of it`
  return `${text.slice(0, max)}\n… [${text.length - max} more characters cut; ${fix}]`
}

const pretty = (json: string): string => {
  try {
    return JSON.stringify(JSON.parse(json), null, 2) ?? 'null'
  } catch {
    return json
  }
}

/** The text the model reads after a run. */
export const formatOutcome = (
  outcome: RunnerDone | RunnerError | undefined,
  calls: number,
  stderr: string,
  maxChars: number,
  projection?: Projection,
): string => {
  const parts: string[] = []
  if (outcome === undefined) {
    parts.push('Error: the sandbox exited without a result.')
    if (stderr.trim() !== '') parts.push(`stderr:\n${clip(stderr.trim(), 2000)}`)
  } else if (outcome.t === 'done') {
    parts.push(clip(pretty(outcome.value), maxChars, projection?.wholeRef))
  } else {
    const message = /^\w*Error: /.test(outcome.message) ? outcome.message : `Error: ${outcome.message}`
    parts.push(clip(message, 4000))
  }
  const logs = outcome?.logs ?? []
  if (logs.length > 0) parts.push(`--- console (${logs.length} lines) ---\n${clip(logs.join('\n'), 4000)}`)
  parts.push(
    projection === undefined
      ? `--- ${calls} MCP call${calls === 1 ? '' : 's'} ---`
      : projectionFooter(projection, outcome),
  )
  return parts.join('\n\n')
}

/**
 * One nested call as the run's footer shows it: its number in the session
 * (`ref`, absent when it failed or was not kept), its size and shape, the
 * earlier call it repeats (`repeatOf`: that call's number, 0 when it has none),
 * and its status: `unfinished` when the run ended before its reply came.
 */
export type CallRecord = {
  ref?: number
  tool: string
  status: 'ok' | 'failed' | 'unfinished'
  chars: number
  shape?: string
  repeatOf?: number
}

/**
 * What a run with output projection reports: its calls, the results it read
 * again with recall() and how old each one was, and the number of a cut result.
 */
export type Projection = {
  calls: CallRecord[]
  recalls: number
  recalled: { ref: number; ageMs: number }[]
  wholeRef?: number
}

const MAX_SHAPE_CHARS = 200
const MAX_KEYS = 8
const SAMPLE = 20

const isEmpty = (v: unknown): boolean =>
  v === null ||
  v === undefined ||
  v === '' ||
  (Array.isArray(v) ? v.every(isEmpty) : typeof v === 'object' && Object.values(v as object).every(isEmpty))

// The keys of many objects in first-seen order, each with its first value that is not empty.
const mergeObjects = (items: Record<string, unknown>[]): Record<string, unknown> => {
  const merged: Record<string, unknown> = {}
  for (const item of items)
    for (const [k, v] of Object.entries(item)) if (!(k in merged) || isEmpty(merged[k])) merged[k] = v
  return merged
}

// A key that reads as a field name: `status`, `next_cursor`, `realName`. Ids,
// emails, ticket keys and other data used as keys do not.
const isFieldName = (key: string): boolean =>
  /^[A-Za-z_$][A-Za-z0-9_$]{0,39}$/.test(key) && (key.match(/\d/g)?.length ?? 0) <= 2

const kindOf = (v: unknown): string =>
  v === null
    ? 'null'
    : Array.isArray(v)
      ? 'array'
      : typeof v === 'object'
        ? `{${Object.keys(v as object)
            .sort()
            .join(',')}}`
        : typeof v

// A map from data to values, such as error counts by service or users by
// name: three keys or more whose values are all of one kind. A record's
// fields differ in kind.
const isMap = (o: Record<string, unknown>): boolean => {
  const values = Object.values(o)
  return values.length >= 3 && values.every(v => kindOf(v) === kindOf(values[0]))
}

// The keys of an object are shown only when they are field names: keys that
// are data would put the data into the context, which the program kept out.
// The merged items of an array are records (their keys repeat), so only the
// spelling of their keys counts.
const shapeAt = (v: unknown, depth: number, isRecord = false): string => {
  if (v === null || v === undefined) return 'null'
  if (Array.isArray(v)) {
    if (v.length === 0) return '[]'
    if (depth >= 2) return `[${v.length}]`
    const sample = v.slice(0, SAMPLE)
    const objects = sample.filter(
      (x): x is Record<string, unknown> => x !== null && typeof x === 'object' && !Array.isArray(x),
    )
    // The items are at the array's own depth: a list of records shows their keys.
    const inner =
      objects.length === sample.length
        ? shapeAt(mergeObjects(objects), depth, objects.length > 1)
        : shapeAt(sample[0], depth + 1)
    return `[${v.length} × ${inner}]`
  }
  if (typeof v === 'object') {
    const keys = Object.keys(v)
    if (keys.length === 0) return '{}'
    const hidden = !keys.every(isFieldName) || (!isRecord && isMap(v as Record<string, unknown>))
    if (depth >= 2 || hidden) return `{${keys.length} key${keys.length === 1 ? '' : 's'}}`
    const fields = keys.slice(0, MAX_KEYS).map(k => {
      const inner = (v as Record<string, unknown>)[k]
      return inner !== null && typeof inner === 'object' ? `${k}: ${shapeAt(inner, depth + 1)}` : k
    })
    const more = keys.length > MAX_KEYS ? [`…+${keys.length - MAX_KEYS}`] : []
    return `{${[...fields, ...more].join(', ')}}`
  }
  if (typeof v === 'string') {
    const lines = v.split('\n').length
    return depth === 0 ? `text, ${lines} line${lines === 1 ? '' : 's'}` : 'string'
  }
  return typeof v
}

/** The structure of a value in one short line: keys, array lengths, nesting to depth 2. */
export const shapeOf = (v: unknown): string => {
  const shape = shapeAt(v, 0)
  return shape.length <= MAX_SHAPE_CHARS ? shape : `${shape.slice(0, MAX_SHAPE_CHARS)}…`
}

/**
 * The shape of a tool's result to show before its next call: shapeOf with no
 * counts, which change from call to call. Undefined for an empty result, which
 * shows no fields.
 */
export const learnedShape = (v: unknown): string | undefined => {
  if (typeof v === 'string') return 'text'
  const shape = shapeOf(v)
    .replace(/\[\d+ × /g, '[')
    .replace(/\[\d+\]/g, '[…]')
    .replace(/\{\d+ keys?\}/g, '{…}')
  return /^(\[\]|\{\}|null)$/.test(shape) ? undefined : shape
}

/** The learned shapes by tool name, newest change last. */
export type Shapes = Record<string, string>

const MAX_SHAPES = 500
// What learnedShape makes: field names, brackets and punctuation. The file is
// in ~/.claude, where the model can write too, so other text is dropped.
const SHAPE = /^[\w$ {}[\]:,.…+]{1,240}$/

/** The shapes file as Shapes, without the entries learnedShape cannot have made. */
export const parseShapes = (text: string): Shapes => {
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return {}
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return {}
  return Object.fromEntries(
    Object.entries(parsed).filter(
      ([tool, shape]) =>
        splitToolName(tool) !== undefined && tool.length <= 200 && typeof shape === 'string' && SHAPE.test(shape),
    ),
  )
}

/**
 * The shapes with the ones a run learned, or undefined when nothing changed.
 * A shape with an empty array does not replace a known one: it hides the
 * fields of the array's items. The oldest change goes first past the limit.
 */
export const mergeShapes = (current: Shapes, learned: ReadonlyMap<string, string>): Shapes | undefined => {
  const next = { ...current }
  let changed = false
  for (const [tool, shape] of learned) {
    if (next[tool] === shape || (next[tool] !== undefined && shape.includes('[]'))) continue
    delete next[tool]
    next[tool] = shape
    changed = true
  }
  if (!changed) return undefined
  const tools = Object.keys(next)
  for (const tool of tools.slice(0, Math.max(0, tools.length - MAX_SHAPES))) delete next[tool]
  return next
}

/** Why saveFile cannot use a name, or undefined: a file name only, no folder. */
export const fileNameError = (name: string): string | undefined =>
  /^[A-Za-z0-9_][A-Za-z0-9_.-]{0,99}$/.test(name) && !name.includes('..')
    ? undefined
    : `saveFile: "${name.slice(0, 60)}" is not a file name; use a name with no folder, such as "issues.csv"`

const csvCell = (v: unknown): string => {
  const text = v === null || v === undefined ? '' : typeof v === 'object' ? JSON.stringify(v) : String(v)
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text
}

// Rows of objects get a header with every key; rows of arrays are the cells.
const toCsv = (rows: readonly unknown[]): string => {
  const isRecord = (r: unknown): r is Record<string, unknown> =>
    r !== null && typeof r === 'object' && !Array.isArray(r)
  if (rows.every(Array.isArray)) return rows.map(r => (r as unknown[]).map(csvCell).join(',')).join('\n')
  if (!rows.every(isRecord)) return rows.map(csvCell).join('\n')
  const keys = [...new Set(rows.flatMap(r => Object.keys(r)))]
  return [keys.map(csvCell).join(','), ...rows.map(r => keys.map(k => csvCell(r[k])).join(','))].join('\n')
}

/** What saveFile writes: text as it is, CSV or JSON lines for an array by the name's extension, else JSON. */
export const fileText = (name: string, value: unknown): string => {
  if (typeof value === 'string') return value
  if (Array.isArray(value) && /\.csv$/i.test(name)) return `${toCsv(value)}\n`
  if (Array.isArray(value) && /\.jsonl$/i.test(name))
    return `${value.map(v => JSON.stringify(v) ?? 'null').join('\n')}\n`
  return `${JSON.stringify(value, null, 2)}\n`
}

/** The argument names of each tool from its calls that worked, newest change last. */
export type ArgNames = Record<string, string[]>

const MAX_ARG_TOOLS = 500
const MAX_ARG_NAMES = 40
const ARG_NAME = /^[A-Za-z_$][A-Za-z0-9_$-]{0,63}$/

/** The names of a call's arguments that can be argument names: never values. */
export const argNamesOf = (args: Record<string, unknown>): string[] => Object.keys(args).filter(k => ARG_NAME.test(k))

/** The argument names file as ArgNames, without the entries a call cannot have made. */
export const parseArgNames = (text: string): ArgNames => {
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return {}
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return {}
  const entries = Object.entries(parsed).flatMap(([tool, names]): [string, string[]][] => {
    if (splitToolName(tool) === undefined || tool.length > 200 || !Array.isArray(names)) return []
    const valid = names.filter((n): n is string => typeof n === 'string' && ARG_NAME.test(n)).slice(0, MAX_ARG_NAMES)
    return valid.length === 0 ? [] : [[tool, valid]]
  })
  return Object.fromEntries(entries)
}

/** The names with the ones a run used, or undefined when nothing is new. The oldest change goes first past the limit. */
export const mergeArgNames = (
  current: ArgNames,
  learned: ReadonlyMap<string, readonly string[]>,
): ArgNames | undefined => {
  const next = { ...current }
  let changed = false
  for (const [tool, names] of learned) {
    const known = next[tool] ?? []
    const added = names.filter(n => !known.includes(n))
    if (added.length === 0) continue
    delete next[tool]
    next[tool] = [...known, ...added].slice(0, MAX_ARG_NAMES)
    changed = true
  }
  if (!changed) return undefined
  const tools = Object.keys(next)
  for (const tool of tools.slice(0, Math.max(0, tools.length - MAX_ARG_TOOLS))) delete next[tool]
  return next
}

// A regular expression literal starts where a value can start.
const REGEX_BEFORE = new Set(['', '(', ',', '=', ':', '[', '!', '&', '|', '?', '{', '}', ';'])

/**
 * The code with the text of comments, strings, template literals and regular
 * expressions as spaces: the same length and lines, so the brackets and
 * commas left are the code's own. Quote characters stay.
 */
export const maskCode = (code: string): string => {
  const out = code.split('')
  const blank = (from: number, to: number) => {
    for (let k = from; k < to; k++) if (out[k] !== '\n') out[k] = ' '
  }
  let last = ''
  let i = 0
  while (i < code.length) {
    const c = code[i]!
    const next = code[i + 1]
    if (c === '/' && next === '/') {
      const end = code.indexOf('\n', i)
      const stop = end < 0 ? code.length : end
      blank(i, stop)
      i = stop
    } else if (c === '/' && next === '*') {
      const end = code.indexOf('*/', i + 2)
      const stop = end < 0 ? code.length : end + 2
      blank(i, stop)
      i = stop
    } else if (c === '"' || c === "'" || c === '`') {
      let k = i + 1
      while (k < code.length && code[k] !== c && !(c !== '`' && code[k] === '\n')) k += code[k] === '\\' ? 2 : 1
      blank(i + 1, Math.min(k, code.length))
      last = c
      i = k + 1
    } else if (c === '/' && REGEX_BEFORE.has(last)) {
      let k = i + 1
      let inClass = false
      while (k < code.length && code[k] !== '\n' && (inClass || code[k] !== '/')) {
        if (code[k] === '[') inClass = true
        else if (code[k] === ']') inClass = false
        k += code[k] === '\\' ? 2 : 1
      }
      blank(i + 1, Math.min(k, code.length))
      last = '/'
      i = k + 1
    } else {
      if (!/\s/.test(c)) last = /[\w$]/.test(c) ? 'a' : c
      i++
    }
  }
  return out.join('')
}

// The ranges of the parts between top-level separators of the bracket that
// opens at `open`, and the index of its closing bracket.
const partsOf = (masked: string, open: number, separators: RegExp): { parts: [number, number][]; close: number } => {
  const parts: [number, number][] = []
  let depth = 0
  let start = open + 1
  for (let i = open; i < masked.length; i++) {
    const c = masked[i]!
    if ('([{'.includes(c)) depth++
    else if (')]}'.includes(c)) {
      depth--
      if (depth === 0) {
        parts.push([start, i])
        return { parts, close: i }
      }
    } else if (depth === 1 && separators.test(c)) {
      parts.push([start, i])
      start = i + 1
    }
  }
  return { parts, close: -1 }
}

// Where the part starts after spaces and comments (spaces in `masked`).
const startOf = (masked: string, [from, to]: [number, number]): number => {
  let i = from
  while (i < to && /\s/.test(masked[i]!)) i++
  return i
}

const unquote = (q: string, text: string): string => {
  if (q !== '"') return text
  try {
    return JSON.parse(`"${text}"`) as string
  } catch {
    return text
  }
}

/** One call("<tool>", ...) in a program: its line and its argument names, or undefined when they are not an object literal of plain keys. */
export type LiteralCall = { tool: string; line: number; keys: string[] | undefined }

/** The calls of a program whose tool name is a string literal. */
export const literalCalls = (code: string): LiteralCall[] => {
  const masked = maskCode(code)
  const found: LiteralCall[] = []
  const at = /(^|[^\w$.])call\s*\(\s*(["'])/g
  for (let m = at.exec(masked); m !== null; m = at.exec(masked)) {
    const quote = m.index + m[0].length - 1
    const end = masked.indexOf(m[2]!, quote + 1)
    if (end < 0) continue
    const tool = code.slice(quote + 1, end)
    const line = code.slice(0, quote).split('\n').length
    const rest = /^\s*(\)|,\s*(\{)?)/.exec(masked.slice(end + 1))
    if (rest === null) continue
    if (rest[1] === ')') {
      found.push({ tool, line, keys: [] })
      continue
    }
    if (rest[2] === undefined) {
      found.push({ tool, line, keys: undefined })
      continue
    }
    const open = end + 1 + rest[0].length - 1
    const { parts, close } = partsOf(masked, open, /,/)
    if (close < 0) continue
    found.push({ tool, line, keys: objectKeys(code, masked, parts) })
  }
  return found
}

// The keys of an object literal, or undefined for a spread, a computed key or a method.
const objectKeys = (code: string, masked: string, parts: [number, number][]): string[] | undefined => {
  const keys: string[] = []
  for (const part of parts) {
    const from = startOf(masked, part)
    const text = code.slice(from, part[1])
    if (masked.slice(from, part[1]).trim() === '') continue
    const plain = /^([A-Za-z_$][\w$]*|\d+)\s*(:|$)/.exec(masked.slice(from, part[1]).trimEnd())
    const quoted = /^(["'])(.*?)\1\s*:/.exec(text)
    if (plain !== null && !(plain[2] === '' && /^\d/.test(plain[1]!))) keys.push(plain[1]!)
    else if (quoted !== null) keys.push(unquote(quoted[1]!, quoted[2]!))
    else return undefined
  }
  return keys
}

/** What a declaration says of a tool's arguments: every name, the required ones, and whether other names are allowed. */
export type ArgSpec = { names: string[]; required: string[]; isOpen: boolean }

/** The top-level properties of an input declaration such as `{ to: string; cc?: string[] }`. */
export const declarationKeys = (declaration: string): ArgSpec | undefined => {
  const masked = maskCode(declaration)
  const open = masked.indexOf('{')
  if (open < 0) return undefined
  const { parts, close } = partsOf(masked, open, /[;,\n]/)
  if (close < 0) return undefined
  const spec: ArgSpec = { names: [], required: [], isOpen: false }
  for (const part of parts) {
    const from = startOf(masked, part)
    const text = declaration.slice(from, part[1]).replace(/^readonly\s+/, '')
    if (text.startsWith('[')) spec.isOpen = true
    const member = /^(?:([A-Za-z_$][\w$]*)|(["'])(.*?)\2)(\?)?\s*:/.exec(text)
    if (member === null) continue
    const name = member[1] ?? unquote(member[2]!, member[3]!)
    spec.names.push(name)
    if (member[4] !== '?') spec.required.push(name)
  }
  // No properties at all: the generated type says nothing useful, so allow any.
  if (spec.names.length === 0) spec.isOpen = true
  return spec
}

/** The number of single-letter edits between two names. */
export const editDistance = (a: string, b: string): number => {
  let row = Array.from({ length: b.length + 1 }, (_, j) => j)
  for (let i = 1; i <= a.length; i++) {
    const next = [i]
    for (let j = 1; j <= b.length; j++)
      next.push(Math.min(row[j]! + 1, next[j - 1]! + 1, row[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1)))
    row = next
  }
  return row[b.length]!
}

const nearest = (name: string, names: readonly string[], most: number): string | undefined => {
  let best: { name: string; d: number } | undefined
  for (const n of names) {
    const d = n.toLowerCase() === name.toLowerCase() ? 0.5 : editDistance(n, name)
    if (d <= most && (best === undefined || d < best.d)) best = { name: n, d }
  }
  return best?.name
}

// A name that earlier calls did not use, close to one they did: a typo.
// Short names differ by one letter at most, so `id` and `ids` both pass.
const typoOf = (key: string, names: readonly string[]): string | undefined =>
  key.length < 4 ? undefined : nearest(key, names, key.length <= 6 ? 1 : 2)

/** A wrong name in a program, found before it runs. `isGuess`: from learned names, not a declaration. */
export type CallProblem = { line: number; text: string; isGuess: boolean }

/**
 * The wrong names in the literal calls of a program: a tool that is not
 * connected, and with a declaration, an unknown or a missing argument. With
 * only the names of earlier calls, a name close to one of them. A deny rule
 * takes a tool out of the session, and the engine cannot check a tool that is
 * not there: so for a server that is connected, the result names both causes.
 */
export const checkCalls = (
  calls: readonly LiteralCall[],
  tools: ReadonlySet<string>,
  specOf: (tool: string) => ArgSpec | undefined,
  learned: ArgNames,
): CallProblem[] => {
  const problems: CallProblem[] = []
  for (const c of calls) {
    if (tools.size > 0 && !tools.has(c.tool) && splitToolName(c.tool) !== undefined) {
      const near = nearest(c.tool, [...tools], 3)
      const guess = near === undefined ? '' : ` (did you mean "${near}"?)`
      const server = splitToolName(c.tool)!.server
      const text = [...tools].some(t => splitToolName(t)?.server === server)
        ? `no tool "${c.tool}" on the connected server "${server}"${guess}; if the name is right, a deny rule hides it`
        : `no MCP tool "${c.tool}" is connected${guess}`
      problems.push({ line: c.line, text, isGuess: false })
      continue
    }
    if (c.keys === undefined) continue
    const spec = specOf(c.tool)
    if (spec !== undefined) {
      for (const key of spec.isOpen ? [] : c.keys.filter(k => !spec.names.includes(k))) {
        const near = nearest(key, spec.names, 3)
        problems.push({
          line: c.line,
          text: `${c.tool}: unknown argument "${key}"${near === undefined ? '' : ` (did you mean "${near}"?)`}`,
          isGuess: false,
        })
      }
      for (const name of spec.required.filter(n => !c.keys!.includes(n))) {
        problems.push({ line: c.line, text: `${c.tool}: missing required argument "${name}"`, isGuess: false })
      }
      continue
    }
    const names = learned[c.tool] ?? []
    for (const key of c.keys.filter(k => !names.includes(k))) {
      const near = typoOf(key, names)
      if (near !== undefined)
        problems.push({
          line: c.line,
          text: `${c.tool}: argument "${key}" is not a name that earlier calls used (did you mean "${near}"?)`,
          isGuess: true,
        })
    }
  }
  return problems
}

/** The result of a program that did not run because of wrong names. */
export const problemReport = (problems: readonly CallProblem[]): string => {
  const lines = problems.map(p => `- line ${p.line}: ${p.text}`)
  const escape = problems.some(p => p.isGuess)
    ? ['If a name is right, pass the arguments as a variable: the check reads only object literals.']
    : []
  return [
    'Error: the program did not run, because some calls have wrong names. No call was made.',
    ...lines,
    ...escape,
  ].join('\n')
}

/** Runs at most `n` tasks at a time; the others wait in the order they came. */
export const limiter = (n: number) => {
  let active = 0
  const queue: (() => void)[] = []
  return <T>(task: () => Promise<T>): Promise<T> =>
    new Promise<T>((resolve, reject) => {
      const start = () => {
        active++
        Promise.resolve()
          .then(task)
          .then(resolve, reject)
          .finally(() => {
            active--
            queue.shift()?.()
          })
      }
      if (active < n) start()
      else queue.push(start)
    })
}

/** A character count, short: 812, 18k, 1.2M. */
export const charCount = (n: number): string =>
  n < 1000 ? String(n) : n < 1_000_000 ? `${Math.round(n / 1000)}k` : `${(n / 1_000_000).toFixed(1)}M`

/** True when a program returned nothing although its calls returned data: a filter that missed. */
export const missedData = (outcome: RunnerDone | RunnerError | undefined, calls: readonly CallRecord[]): boolean => {
  if (outcome?.t !== 'done' || !calls.some(c => c.status === 'ok' && c.chars > 2)) return false
  try {
    return isEmpty(JSON.parse(outcome.value))
  } catch {
    return false
  }
}

const MAX_CALL_LINES = 8

// JSON with sorted keys, so two calls with the same arguments match.
const stable = (v: unknown): string =>
  Array.isArray(v)
    ? `[${v.map(stable).join(',')}]`
    : v !== null && typeof v === 'object'
      ? `{${Object.keys(v)
          .sort()
          .map(k => `${JSON.stringify(k)}:${stable((v as Record<string, unknown>)[k])}`)
          .join(',')}}`
      : (JSON.stringify(v) ?? 'null')

/** The identity of a call: the tool and its arguments. Two equal keys are the same call. */
export const callKey = (tool: string, args: Record<string, unknown>): string => `${tool}\n${stable(args)}`

const callLine = (c: CallRecord): string => {
  const id = c.ref === undefined ? '-' : `#${c.ref}`
  if (c.status === 'unfinished') return `${id} ${c.tool} did not finish`
  if (c.status === 'failed') return `${id} ${c.tool} failed`
  const repeat = c.repeatOf === undefined || c.repeatOf === 0 ? '' : `, the same call as #${c.repeatOf}`
  return `${id} ${c.tool} ${charCount(c.chars)}${repeat} ${c.shape ?? ''}`.trimEnd()
}

// Many calls: one line per tool, with the shape of its first result.
const groupLines = (calls: readonly CallRecord[]): string[] => {
  const byTool = new Map<string, CallRecord[]>()
  for (const c of calls) byTool.set(c.tool, [...(byTool.get(c.tool) ?? []), c])
  return [...byTool].map(([tool, group]) => {
    const kept = group.filter(c => c.ref !== undefined).map(c => c.ref!)
    const ids = kept.length === 0 ? '-' : kept.length === 1 ? `#${kept[0]}` : `#${kept[0]}…#${kept.at(-1)}`
    const unfinished = group.filter(c => c.status === 'unfinished').length
    const failed = group.filter(c => c.status === 'failed').length
    const chars = group.reduce((n, c) => n + c.chars, 0)
    const first = group.find(c => c.status === 'ok')
    const failures = `${failed === 0 ? '' : `, ${failed} failed`}${unfinished === 0 ? '' : `, ${unfinished} did not finish`}`
    return `${ids} ${tool} ×${group.length}${failures} ${charCount(chars)} ${first?.shape ?? ''}`.trimEnd()
  })
}

/** How old a kept result is, short: 40 s old, 12 min old, 3 h old. */
export const age = (ms: number): string => {
  const s = Math.max(0, Math.round(ms / 1000))
  return s < 60 ? `${s} s old` : s < 3600 ? `${Math.round(s / 60)} min old` : `${Math.round(s / 3600)} h old`
}

/** The footer of a run with output projection: what came in, what went out, and how to get it again. */
export const projectionFooter = (p: Projection, outcome: RunnerDone | RunnerError | undefined): string => {
  const n = p.calls.length
  const inChars = p.calls.reduce((sum, c) => sum + c.chars, 0)
  const outChars = outcome?.t === 'done' ? outcome.value.length : 0
  const recalls = p.recalls === 0 ? '' : `, ${p.recalls} recall${p.recalls === 1 ? '' : 's'}`
  const head = `--- ${n} MCP call${n === 1 ? '' : 's'}${recalls}: ${charCount(inChars)} characters in, ${charCount(outChars)} out ---`
  const recalled =
    p.recalled.length === 0
      ? []
      : [
          `recalled: ${[...new Map(p.recalled.map(r => [r.ref, r])).values()].map(r => `#${r.ref} (${age(r.ageMs)})`).join(', ')}`,
        ]
  if (n === 0) return [head, ...recalled].join('\n')
  const lines = n <= MAX_CALL_LINES ? p.calls.map(callLine) : groupLines(p.calls)
  const missed = missedData(outcome, p.calls)
    ? ['The result is empty, but the calls returned data: check the shapes.']
    : []
  return [head, ...lines, ...recalled, ...missed, 'await recall(n) returns result #n again, with no new call.'].join(
    '\n',
  )
}

const words = (text: string): string[] =>
  text
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(w => w.length > 1)

/** Ranks tools by how many query words their name and description hold. */
export const rankTools = (tools: readonly ToolEntry[], query: string, limit: number): ToolEntry[] => {
  const wanted = words(query)
  const scored = tools.map(tool => {
    const name = tool.name.toLowerCase()
    const description = tool.description.toLowerCase()
    let score = 0
    for (const w of wanted) {
      if (name.includes(w)) score += 3
      else if (description.includes(w)) score += 1
    }
    return { tool, score }
  })
  return scored
    .filter(s => wanted.length === 0 || s.score > 0)
    .sort((a, b) => b.score - a.score || a.tool.name.localeCompare(b.tool.name))
    .slice(0, limit)
    .map(s => s.tool)
}

/**
 * The input declaration of one tool in the engine's generated MCP types
 * (`interface McpToolInputs { mcp__x__y: { ... } }`), or undefined. The engine
 * quotes a key only when it is not a JavaScript name ("mcp__x__get-issue").
 */
export const extractDeclaration = (dts: string, name: string): string | undefined => {
  const n = name.replace(/[$.*+?^()[\]{}|\\]/g, '\\$&')
  const key = new RegExp(`(?:^|[{;])[ \\t]*(?:"${n}"|'${n}'|${n}):`, 'm').exec(dts)
  if (key === null) return undefined
  const colon = key.index + key[0].length - 1
  const open = dts.indexOf('{', colon)
  // A type that is not an object literal (a named type, Record<…>) gives nothing.
  if (open < 0 || dts.slice(colon + 1, open).trim() !== '') return undefined
  let depth = 0
  for (let i = open; i < dts.length; i++) {
    const c = dts[i]
    if (c === '{') depth++
    else if (c === '}') {
      depth--
      if (depth === 0) return dedent(dts.slice(open, i + 1))
    }
  }
  return undefined
}

// Re-indents a block cut from the middle of a file: its closing brace at
// column 0, everything else shifted by the same amount.
const dedent = (block: string): string => {
  const lines = block.split('\n')
  if (lines.length === 1) return block
  const last = lines[lines.length - 1]!
  const cut = last.length - last.trimStart().length
  return [lines[0], ...lines.slice(1).map(l => l.slice(Math.min(cut, l.length - l.trimStart().length)))].join('\n')
}

export const RUN_DESCRIPTION = `Run a JavaScript program that calls MCP tools, and get back only what it returns. Use it instead of direct MCP tool calls, for one call or many: intermediate data stays out of the context.

The program is the body of an async function. Available:
- await call("mcp__<server>__<tool>", args) -> the tool result (parsed JSON when the tool returns JSON, else text)
- await sleep(ms) -> waits, to poll a slow job; the time limit of the run still applies
- await saveFile(name, data) -> writes data to a file and returns its path: text as it is, CSV or JSON lines for an array with a .csv or .jsonl name, else JSON; use it for data too large to return
- await readFile(path) -> the text of a file in the project, or of a file from saveFile
- await resources(server?) -> the MCP resources, each with its server and uri; await readResource(server, uri) -> its contents
- await lib.<name>(args) -> a saved function; search_tools lists them
- console.log(...) -> shown after the result
- return <value> -> the result, as JSON

A failed call throws an Error (catch it to continue). Promise.all runs calls in parallel, 8 at a time. There is no require, fetch, process or setTimeout: only these functions.

Find tools, their argument types, result shapes, usage hints and saved functions with search_tools first. When a task took more than one try (a search, a tool, an argument, a result format), propose what worked with add_hint, so the next session gets it right the first time. When a working program does a task that comes back (all pages of a search, a join of two tools), propose it with save_function. Do not wait for the person to ask.

Example:
const issues = await call("mcp__linear__list_issues", { assignee: "me" })
const open = issues.filter(i => i.state !== "Done")
return open.map(i => ({ id: i.id, title: i.title }))`

export const SEARCH_DESCRIPTION = `Find MCP tools to use from run_code. Give keywords (for example "jira issue create"); get the matching tool names, their descriptions and, when known, their argument types and result shapes. Use an empty query to list all MCP tools.`

/** After the header of a search_tools result with a tool that has no argument types: said once, not in each block. */
export const UNTYPED_NOTE = `\nWhere args has no types, ToolSearch "select:<name>" shows the schema.`

/**
 * The note after a run that worked where earlier tries did not: the servers
 * whose calls failed before and work now, and the searches that found nothing.
 * Also after a second run with a tool of a server that has no hint (`probed`,
 * tool names): the first run was often a probe of its arguments or result format.
 */
export const hintNudge = (
  servers: readonly string[],
  missedSearches: readonly string[],
  probed: readonly string[] = [],
): string => {
  if (servers.length === 0 && missedSearches.length === 0 && probed.length === 0) return ''
  const failed = servers.length === 0 ? [] : [`Calls to ${servers.join(', ')} failed earlier and work now.`]
  const missed =
    missedSearches.length === 0
      ? []
      : [`search_tools found nothing for ${missedSearches.map(q => JSON.stringify(q)).join(', ')}.`]
  const again =
    probed.length === 0
      ? []
      : [
          `An earlier run called ${probed.join(', ')} too, and no hint covers ${probed.length === 1 ? 'its server' : 'their servers'}.`,
        ]
  return `## Worth a hint\n\n${[...failed, ...missed, ...again].join(' ')} If you had to find out how it works (the search words, the tool, an argument, a result format), propose it with add_hint now, one short fact per hint, so the next session gets it right the first time.`
}

/**
 * The note after a program that did a task worth keeping: many calls, or
 * calls to more than one tool, with no saved function.
 */
export const functionNudge = (calls: number, tools: readonly string[]): string =>
  `## Worth a saved function\n\nThis program made ${calls} call${calls === 1 ? '' : 's'} to ${tools.join(', ')}. If the person can ask for this task again, propose the program with save_function now: pass ids, dates and queries as arguments.`

/**
 * The note after nested calls that needed an approval (no rule decided them)
 * and were refused. Without an allow rule they are refused each time (claude -p,
 * and auto mode in some Claude Code versions); only the person can add the rule.
 */
export const approvalNote = (tools: readonly string[]): string => {
  if (tools.length === 0) return ''
  const names = tools.join(', ')
  const one = tools.length === 1
  return `## No allow rule\n\nNo allow rule matches ${names}, and ${one ? 'its call was' : 'their calls were'} refused. Without an allow rule, the same call is refused again. If the person wants programs to call ${one ? 'this tool' : 'these tools'}, ask them to add ${names} to permissions.allow in ~/.claude/settings.json. Do not change the settings yourself.`
}

files.hooks/functions.ts:
// Pure helpers for saved functions: the file format, the checks of a
// proposal, which functions a program uses, and which ones search_tools
// shows. No `$` here, so tests can call them directly.
//
// A function file is markdown: front matter with the name and description,
// then one js code block with an async function expression.

import { oneLine, transferBlock } from './hints'

/** A saved function, or a proposal of one (`why`, only while it is pending). */
export type SavedFunction = { name: string; description: string; code: string; path: string; why?: string }

const NAME = /^[A-Za-z_$][\w$]{0,39}$/
const MAX_CODE_CHARS = 8000
const MAX_DESCRIPTION_CHARS = 200

/** Why a proposal cannot be saved, or undefined. */
export const functionError = (name: string, description: string, code: string): string | undefined => {
  if (!NAME.test(name)) return 'name must be a JavaScript name of 40 characters at most, such as "searchAllIssues"'
  if (description === '' || description.length > MAX_DESCRIPTION_CHARS)
    return `description is one sentence (${MAX_DESCRIPTION_CHARS} characters at most)`
  if (code.length > MAX_CODE_CHARS) return `code is ${code.length} characters, more than ${MAX_CODE_CHARS}`
  if (!/^async\b/.test(code)) return 'code must be an async function expression, such as async ({ jql }) => { ... }'
  if (code.includes('```')) return 'code must not contain ```'
  return undefined
}

/** The text of a function file. */
export const formatFunction = (f: Omit<SavedFunction, 'path'>): string =>
  [
    '---',
    `name: ${f.name}`,
    `description: ${oneLine(f.description)}`,
    ...(f.why === undefined ? [] : [`why: ${oneLine(f.why)}`]),
    '---',
    '',
    '```js',
    f.code.trim(),
    '```',
    '',
  ].join('\n')

/** A proposal as a block for the model of another session (see canApprove). */
export const functionTransfer = (f: Omit<SavedFunction, 'path'>): string =>
  transferBlock([
    'Propose this code-mode function with save_function. Keep the code as it is.',
    `name: ${f.name}`,
    `description: ${oneLine(f.description)}`,
    ...(f.why === undefined ? [] : [`why: ${oneLine(f.why)}`]),
    'code:',
    '```js',
    f.code.trim(),
    '```',
  ])

/** A function file as a SavedFunction, or undefined when it is not one. */
export const parseFunction = (text: string, path: string): SavedFunction | undefined => {
  const front = /^---\n([\s\S]*?)\n---\n/.exec(text)
  if (front === null) return undefined
  const fields = new Map(
    front[1]!.split('\n').flatMap(line => {
      const at = line.indexOf(':')
      return at < 0 ? [] : [[line.slice(0, at).trim(), line.slice(at + 1).trim()] as const]
    }),
  )
  const code = /```js\n([\s\S]*?)\n```/.exec(text.slice(front[0].length))?.[1]?.trim()
  const name = fields.get('name') ?? ''
  const description = fields.get('description') ?? ''
  if (code === undefined || functionError(name, description, code) !== undefined) return undefined
  const why = fields.get('why')
  return { name, description, code, path, ...(why === undefined ? {} : { why }) }
}

const USE = /\blib\s*(?:\.\s*([A-Za-z_$][\w$]*)|\[\s*(["'])([A-Za-z_$][\w$]*)\2\s*\])/g

/** The names a program uses as lib.<name>, and the names those functions use in turn. */
export const usedFunctions = (code: string, functions: ReadonlyMap<string, SavedFunction>): string[] => {
  const used = new Set<string>()
  const queue = [code]
  while (queue.length > 0) {
    for (const m of queue.pop()!.matchAll(USE)) {
      const name = m[1] ?? m[3]!
      const f = functions.get(name)
      if (f === undefined || used.has(name)) continue
      used.add(name)
      queue.push(f.code)
    }
  }
  return [...used]
}

/** The parameters of a function's code, as its signature shows them: `({ jql, cloudId })`. */
export const signatureOf = (code: string): string => {
  const params = /^async\s*(?:function\b[^(]*)?(\([^)]*\)|[A-Za-z_$][\w$]*)/.exec(code)?.[1] ?? '(args)'
  return oneLine(params.startsWith('(') ? params : `(${params})`)
}

/**
 * The functions for a search_tools result: those whose code names one of
 * the found tools, and those whose name or description holds a word of the
 * query. An empty query gives all of them.
 */
export const functionsFor = (
  functions: readonly SavedFunction[],
  tools: readonly string[],
  query: string,
): SavedFunction[] => {
  const wanted = query
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(w => w.length > 1)
  return functions.filter(
    f =>
      wanted.length === 0 ||
      tools.some(t => f.code.includes(t)) ||
      wanted.some(w => f.name.toLowerCase().includes(w) || f.description.toLowerCase().includes(w)),
  )
}

// Above this many line pairs between the equal first and last lines, codeDiff
// shows all old lines, then all new ones: the table of common lines grows
// with the product of the two sizes.
const MAX_DIFF_CELLS = 250_000

/**
 * The change from one function's code to another, as one unified-diff hunk
 * with every line, so the card shows the whole new code with its changes.
 */
export const codeDiff = (before: string, after: string): string => {
  const a = before.split('\n')
  const b = after.split('\n')
  const head = `@@ -1,${a.length} +1,${b.length} @@`
  // The equal lines at the start and at the end need no table.
  let start = 0
  while (start < a.length && start < b.length && a[start] === b[start]) start++
  let end = 0
  while (end < a.length - start && end < b.length - start && a[a.length - 1 - end] === b[b.length - 1 - end]) end++
  const same = (lines: string[]) => lines.map(l => ` ${l}`)
  const x = a.slice(start, a.length - end)
  const y = b.slice(start, b.length - end)
  const middle: string[] = []
  if (x.length * y.length > MAX_DIFF_CELLS) {
    middle.push(...x.map(l => `-${l}`), ...y.map(l => `+${l}`))
  } else {
    // common[i][j]: the most lines that x[i..] and y[j..] have in common, in order.
    const common = Array.from({ length: x.length + 1 }, () => new Uint32Array(y.length + 1))
    for (let i = x.length - 1; i >= 0; i--) {
      for (let j = y.length - 1; j >= 0; j--) {
        common[i]![j] = x[i] === y[j] ? common[i + 1]![j + 1]! + 1 : Math.max(common[i + 1]![j]!, common[i]![j + 1]!)
      }
    }
    let i = 0
    let j = 0
    while (i < x.length || j < y.length) {
      if (i < x.length && j < y.length && x[i] === y[j]) {
        middle.push(` ${x[i++]}`)
        j++
      } else if (i < x.length && (j === y.length || common[i + 1]![j]! >= common[i]![j + 1]!)) middle.push(`-${x[i++]}`)
      else middle.push(`+${y[j++]}`)
    }
  }
  return [head, ...same(a.slice(0, start)), ...middle, ...same(a.slice(a.length - end))].join('\n')
}

/** The saved functions of a run that an error came from: a frame in their file, or a compile error. */
export const failedFunctions = (message: string, names: readonly string[]): string[] =>
  names.filter(n => message.includes(`lib/${n}.js:`) || message.includes(`lib.${n} does not compile`))

/** The note after a run that failed in a saved function. */
export const functionFixNudge = (names: readonly string[]): string =>
  names.length === 0
    ? ''
    : `## A saved function failed\n\nThe error comes from ${names.map(n => `lib.${n}`).join(', ')}. If its code is wrong now (a tool or its result changed), read it with return lib.<name>.toString(), fix it, and propose the fix with save_function under the same name.`

/** The functions section of a search_tools result. */
export const formatFunctions = (functions: readonly SavedFunction[]): string =>
  functions.length === 0
    ? ''
    : [
        '## Saved functions',
        '',
        'Call them in run_code as await lib.<name>(args). The person approved each one.',
        ...functions.map(f => `- lib.${f.name}${signatureOf(f.code)}: ${f.description}`),
      ].join('\n')

export const SAVE_FUNCTION_DESCRIPTION = `Propose a program part as a saved function, for a task that comes back. Programs in later sessions then call it as await lib.<name>(args), and search_tools lists it. The function has no effect until the person reads the code and approves it.

Save only code that worked in run_code in this session. It must be an async function expression with one argument and no data of the person in it: pass ids, keys and queries as arguments.

To change a saved function, read its code with return lib.<name>.toString() in run_code, then propose the new code under the same name.`

files.hooks/paths.ts:
// Where code-mode keeps its files: the folder .claude/code-mode in HOME (the
// person's) and in the project root. Every path into it is made here, so the
// loaders and the hint-file guard always name the same folders.
// tests/code.check.mjs fails when another file in hooks/ types one out.

const APP = 'code-mode'
const HINTS = 'hints'
const FUNCTIONS = 'functions'

/** A path in code-mode's folder under `root`: HOME or the project root. */
export const codeModePath = (root: string, ...parts: string[]): string => [root, '.claude', APP, ...parts].join('/')

/** The hint folder under HOME or the project root. */
export const hintsFolder = (root: string): string => codeModePath(root, HINTS)

/** The saved-function folder under HOME. */
export const functionsFolder = (home: string): string => codeModePath(home, FUNCTIONS)

/**
 * The folders whose files steer the model, as written: the person's and the
 * project's hints (the project's even while projectHints is off, so none can
 * be planted to load later), and the person's saved functions. Only an
 * approval writes them; the model's own tools may not. An empty root has none.
 */
export const guardedDirs = (home: string, project: string): string[] => [
  ...(home ? [hintsFolder(home), functionsFolder(home)] : []),
  ...(project ? [hintsFolder(project)] : []),
]

// Read-only programs that may name the folder `code-mode` itself. They may not
// name `hints` or `functions`, and an argument is never the program.
const READ_ONLY = new Set(['ls', 'du', 'cat', 'head', 'tail', 'wc', 'stat', 'file', 'rg', 'grep'])
const WRAPPERS = new Set(['sudo', 'env', 'command'])
const ASSIGNMENT = /^[A-Za-z_][A-Za-z0-9_]*=/

const escape = (text: string): string => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

// Bash POSIX classes, as ASCII. The guarded names are ASCII.
const POSIX: Record<string, string> = {
  alnum: '0-9A-Za-z',
  alpha: 'A-Za-z',
  ascii: '\\x00-\\x7F',
  blank: '\\t ',
  cntrl: '\\x00-\\x1F\\x7F',
  digit: '0-9',
  graph: '\\x21-\\x7E',
  lower: 'a-z',
  print: '\\x20-\\x7E',
  punct: '!-/:-@\\[-`{-~',
  space: '\\t\\n\\v\\f\\r ',
  upper: 'A-Z',
  word: '0-9A-Za-z_',
  xdigit: '0-9A-Fa-f',
}

const classLiteral = (ch: string): string => (/[\\\]^/-]/.test(ch) ? `\\${ch}` : ch)

// One Bash bracket expression at `start`, or null when it cannot be translated.
const bracketAt = (part: string, start: number): { source: string; next: number } | null => {
  const at = (index: number): string => part.charAt(index)
  let i = start + 1
  let neg = false
  if (at(i) === '!' || at(i) === '^') {
    neg = true
    i++
  }
  let body = ''
  if (at(i) === ']') {
    body += '\\]'
    i++
  }
  while (i < part.length && at(i) !== ']') {
    if (at(i) === '[' && (at(i + 1) === ':' || at(i + 1) === '.' || at(i + 1) === '=')) {
      const kind = at(i + 1)
      const mark = `${kind}]`
      const end = part.indexOf(mark, i + 2)
      if (end < 0 || kind !== ':') return null
      const mapped = POSIX[part.slice(i + 2, end)]
      if (mapped === undefined) return null
      body += mapped
      i = end + mark.length
      continue
    }
    if (at(i + 1) === '-' && i + 2 < part.length && at(i + 2) !== ']') {
      if (at(i) > at(i + 2)) return null
      body += `${classLiteral(at(i))}-${classLiteral(at(i + 2))}`
      i += 3
      continue
    }
    body += classLiteral(at(i))
    i++
  }
  if (at(i) !== ']') return null
  return { source: neg ? `[^${body}]` : `[${body}]`, next: i + 1 }
}

// A glob part as a regular expression, or null when a bracket or brace cannot be translated.
const globSource = (part: string): string | null => {
  let out = ''
  for (let i = 0; i < part.length; ) {
    const ch = part.charAt(i)
    if (ch === '*') {
      out += '.*'
      i++
      continue
    }
    if (ch === '?') {
      out += '.'
      i++
      continue
    }
    if (ch === '[') {
      const bracket = bracketAt(part, i)
      if (bracket === null) return null
      out += bracket.source
      i = bracket.next
      continue
    }
    if (ch === '{') {
      const end = part.indexOf('}', i + 1)
      if (end < 0) return null
      const alts = part.slice(i + 1, end).split(',')
      const mapped: string[] = []
      for (const alt of alts) {
        const source = globSource(alt)
        if (source === null) return null
        mapped.push(source)
      }
      out += `(${mapped.join('|')})`
      i = end + 1
      continue
    }
    out += escape(ch)
    i++
  }
  return out
}

const low = (part: string): string => part.toLowerCase()

// True when a glob segment can be `name`. Null when the pattern cannot be read.
const globMatch = (segment: string, name: string): boolean | null => {
  try {
    const source = globSource(segment)
    if (source === null) return null
    return new RegExp(`^${source}$`, 'i').test(name)
  } catch {
    return null
  }
}

type Risk = { hints: boolean; app: boolean; unsafe: boolean; claude: boolean }

const riskOfSegment = (segment: string): Risk => {
  const none = { hints: false, app: false, unsafe: false, claude: false }
  if (segment === '' || segment === '.') return none
  if (segment === '..' || /[$`{]/.test(segment)) return { ...none, unsafe: true }
  if (!/[*?[]/.test(segment)) {
    const name = low(segment)
    return {
      hints: name === HINTS || name === FUNCTIONS,
      app: name === APP,
      unsafe: false,
      claude: name === '.claude',
    }
  }
  const hints = globMatch(segment, HINTS)
  const functions = globMatch(segment, FUNCTIONS)
  const app = globMatch(segment, APP)
  const claude = globMatch(segment, '.claude')
  if (hints === null || functions === null || app === null || claude === null)
    return { hints: false, app: false, unsafe: true, claude: false }
  return { hints: hints || functions, app, unsafe: false, claude }
}

const segmentsOf = (word: string): string[] => {
  const parts: string[] = []
  for (const part of word.split(/[/=]/)) if (part !== '' && part !== '.') parts.push(part)
  return parts
}

const absolute = (word: string): boolean => word.startsWith('/') || word.startsWith('~')

// The risk of each segment of a word. `code-mode` is the guarded folder only
// right under `.claude`, or at the start of a relative path, which can be
// under `.claude`. So `/src/code-mode` is another folder (`elsewhere`), unless
// a symbolic link leads it into `.claude`.
const risksOf = (word: string): (Risk & { elsewhere: boolean })[] => {
  const risks: (Risk & { elsewhere: boolean })[] = []
  for (const part of word.split('=')) {
    let prev: Risk | null = null
    for (const segment of segmentsOf(part)) {
      const risk = riskOfSegment(segment)
      const parentCanBeClaude = prev === null ? !absolute(part) : prev.claude
      risks.push({ ...risk, app: risk.app && parentCanBeClaude, elsewhere: risk.app && !parentCanBeClaude })
      prev = risk
    }
  }
  return risks
}

// `{a,b}` expands with its prefix and suffix. A brace that does not close is unsafe.
const expandBraces = (word: string): string[] | null => {
  let depth = 0
  let start = -1
  for (let i = 0; i < word.length; i++) {
    const ch = word.charAt(i)
    if (ch === '{') {
      if (depth === 0) start = i
      depth++
      continue
    }
    if (ch !== '}') continue
    if (depth === 0) return null
    depth--
    if (depth !== 0 || start < 0) continue
    const body = word.slice(start + 1, i)
    const braceAt = start
    start = -1
    if (!body.includes(',')) continue
    const alts: string[] = []
    let alt = ''
    let nest = 0
    for (const c of body) {
      if (c === '{') nest++
      if (c === '}' && nest > 0) nest--
      if (c === ',' && nest === 0) {
        alts.push(alt)
        alt = ''
      } else alt += c
    }
    alts.push(alt)
    if (alts.length > 32) return null
    const head = word.slice(0, braceAt)
    const tail = word.slice(i + 1)
    const out: string[] = []
    for (const piece of alts) {
      const next = expandBraces(head + piece + tail)
      if (next === null) return null
      out.push(...next)
      if (out.length > 32) return null
    }
    return out
  }
  if (depth !== 0) return null
  return [word]
}

// `commands` holds the words with each quoted or escaped glob, brace, `$`,
// or backtick as LITERAL, since the shell does not expand it. `scripts` holds
// the words as a shell that runs them again reads them.
type Parsed = { commands: string[][]; scripts: string[]; redirect: boolean }

// Not in any guarded name, and not a glob or an expansion.
const LITERAL = '\uE000'
const EXPANDS = '*?[]{}$`'

// Quotes and backslashes come off. `&&`, `|`, `;`, `(`, `)`, and newlines
// separate programs, and `<` ends a word. `>` marks an output redirection. A
// quote that never ends is unsafe.
const parseCommand = (command: string): Parsed | null => {
  const commands: string[][] = []
  const scripts: string[] = []
  let words: string[] = []
  let buf = ''
  let lit = ''
  let quote: "'" | '"' | null = null
  let redirect = false
  const add = (ch: string, literal: boolean) => {
    buf += ch
    lit += literal && EXPANDS.includes(ch) ? LITERAL : ch
  }
  const flushWord = () => {
    if (buf.length > 0) {
      scripts.push(buf)
      words.push(lit)
      buf = ''
      lit = ''
    }
  }
  const flushCommand = () => {
    flushWord()
    if (words.length > 0) commands.push(words)
    words = []
  }
  for (let i = 0; i < command.length; i++) {
    const ch = command.charAt(i)
    if (quote === "'") {
      if (ch === "'") quote = null
      else add(ch, true)
      continue
    }
    if (quote === '"') {
      if (ch === '\\') {
        const next = command.charAt(i + 1)
        if (next === '') return null
        add('"\\`$\n'.includes(next) ? next : ch, true)
        if ('"\\`$\n'.includes(next)) i++
        continue
      }
      if (ch === '"') quote = null
      else add(ch, ch !== '$' && ch !== '`')
      continue
    }
    if (ch === '\\') {
      const next = command.charAt(i + 1)
      if (next === '') return null
      add(next, true)
      i++
      continue
    }
    if (ch === "'" || ch === '"') {
      quote = ch
      continue
    }
    if (ch === '&' && command.charAt(i + 1) === '>') {
      redirect = true
      flushWord()
      i++
      continue
    }
    if (ch === '>') {
      redirect = true
      if (/^\d+$/.test(buf)) {
        buf = ''
        lit = ''
      }
      flushWord()
      if (command.charAt(i + 1) === '>') i++
      else if (command.charAt(i + 1) === '&') i++
      continue
    }
    if ((ch === '&' && command.charAt(i + 1) === '&') || (ch === '|' && command.charAt(i + 1) === '|')) {
      flushCommand()
      i++
      continue
    }
    if ('|&;\n()'.includes(ch)) {
      flushCommand()
      continue
    }
    if (' \t\r<'.includes(ch)) {
      flushWord()
      continue
    }
    add(ch, false)
  }
  if (quote !== null) return null
  flushCommand()
  const expanded: string[][] = []
  for (const argv of commands) {
    const flat: string[] = []
    for (const word of argv) {
      const alts = expandBraces(word)
      if (alts === null) return null
      flat.push(...alts)
    }
    if (flat.length > 0) expanded.push(flat)
  }
  return { commands: expanded, scripts, redirect }
}

// The program name: after assignments and after sudo, env, or command.
const programAt = (argv: string[]): { name: string; index: number } | null => {
  let i = 0
  while (i < argv.length && ASSIGNMENT.test(argv[i] ?? '')) i++
  while (i < argv.length && WRAPPERS.has(low(argv[i] ?? ''))) {
    i++
    while (i < argv.length && (argv[i] ?? '').startsWith('-')) {
      const flag = argv[i] ?? ''
      i++
      if (flag === '-u' || flag === '--user' || flag === '-g' || flag === '--group') {
        if (i >= argv.length) return null
        i++
      }
    }
    while (i < argv.length && ASSIGNMENT.test(argv[i] ?? '')) i++
  }
  const name = argv[i]
  if (name === undefined || name === '') return null
  return { name: low(name), index: i }
}

const operandPaths = (argv: string[], from: number): string[] => {
  const paths: string[] = []
  let flags = true
  for (let i = from + 1; i < argv.length; i++) {
    const word = argv[i] ?? ''
    if (flags && word === '--') {
      flags = false
      continue
    }
    if (flags && word.startsWith('-')) continue
    flags = false
    paths.push(word)
  }
  return paths
}

// Programs that run a word as a script, as `bash -c` or `eval` do. A word with
// one of the SCRIPT characters can then hide a command.
const SHELLS = ['sh', 'bash', 'zsh', 'dash', 'ksh', 'fish', 'eval', 'source', 'watch', 'su', 'script', 'flock']
const SCRIPT = /[\s;&|<>()'"\\]/

// The first token of the word, so `env -S "bash -c ..."` counts. A glob such
// as `/bin/b?sh` counts when it can be a shell or cannot be read.
const isShell = (word: string): boolean => {
  const head = word.trim().split(/\s+/)[0] ?? ''
  const name = low(head.slice(head.lastIndexOf('/') + 1))
  if (!/[*?[]/.test(name)) return SHELLS.includes(name)
  return SHELLS.some(shell => globMatch(name, shell) !== false)
}

const runsShell = (commands: string[][]): boolean =>
  commands.some(argv => programAt(argv)?.name === '.' || argv.some(isShell))

const writesOut = (argv: string[]): boolean =>
  argv.some(word => word === '-o' || word === '--output' || word.startsWith('--output=') || low(word) === 'tee')

/**
 * True when a shell command could name a guarded folder. Fail closed.
 * Quotes and backslashes come off, and braces expand. A quoted or escaped
 * glob or brace is literal, and so is a `$` in single quotes or after a
 * backslash. A word that is `hints` or `functions`, a `..`, a pattern that
 * cannot be read, or a relative path after `cd` into `.claude` is denied. A
 * `code-mode` under `.claude`, or at the start of a relative path, is denied
 * unless every program is read-only, with no `>`, `>>`, `tee`, or `-o`, and
 * no program outside that list in a pipeline. So is a `code-mode` elsewhere
 * when another word ends in `.claude`, as `ln -s` can join the two. The
 * Bash guard resolves the other `code-mode` paths (codeModePaths).
 * When the command runs a shell, a word with spaces, quotes, backslashes, or
 * shell operators is also read as a command of its own.
 */
export const namesGuardedDir = (command: string): boolean => {
  const parsed = parseCommand(command)
  if (parsed === null) return true
  if (runsShell(parsed.commands) && parsed.scripts.some(word => SCRIPT.test(word) && namesGuardedDir(word))) return true
  let hints = false
  let app = false
  let unsafe = false
  let claude = false
  let elsewhere = false
  let joined = false
  let underClaude = false
  let relative = false
  let pure = parsed.commands.length > 0 && !parsed.redirect
  for (const argv of parsed.commands) {
    const program = programAt(argv)
    if (program === null || !READ_ONLY.has(program.name) || writesOut(argv)) pure = false
    for (const word of argv) {
      let wordElsewhere = false
      for (const risk of risksOf(word)) {
        hints ||= risk.hints
        app ||= risk.app
        unsafe ||= risk.unsafe
        wordElsewhere ||= risk.elsewhere
      }
      // Another word that ends in `.claude`: `ln -s ~/.claude /tmp/x` makes
      // `/tmp/x/code-mode` the guarded folder.
      const wordClaude = riskOfSegment(segmentsOf(word).at(-1) ?? '').claude
      joined ||= (wordClaude && elsewhere) || (wordElsewhere && claude)
      claude ||= wordClaude
      elsewhere ||= wordElsewhere
    }
    if (program !== null && underClaude && program.name !== 'cd') {
      const paths = operandPaths(argv, program.index)
      if (paths.length === 0 || paths.some(word => !absolute(word))) relative = true
    }
    if (program?.name === 'cd') {
      const dest = operandPaths(argv, program.index)[0]
      if (underClaude && dest !== undefined && !absolute(dest)) relative = true
      if (
        dest !== undefined &&
        segmentsOf(dest).some(segment => riskOfSegment(segment).claude || riskOfSegment(segment).unsafe)
      )
        underClaude = true
    }
  }
  if (unsafe || hints || relative) return true
  return (app || joined) && !pure
}

/**
 * Each path in a command up to a `code-mode` folder, as written, or null when
 * one has a glob or a quoted glob character. The Bash guard resolves them, as
 * a symbolic link can lead a path such as `/tmp/x/code-mode` into `.claude`.
 */
export const codeModePaths = (command: string): string[] | null => {
  const parsed = parseCommand(command)
  if (parsed === null) return null
  const paths: string[] = []
  for (const argv of parsed.commands)
    for (const word of argv)
      for (const part of word.split('=')) {
        const segments = part.split('/')
        for (let i = 0; i < segments.length; i++) {
          if (!riskOfSegment(segments[i] ?? '').app) continue
          const path = segments.slice(0, i + 1).join('/')
          if (/[*?[]/.test(path) || path.includes(LITERAL)) return null
          paths.push(path)
        }
      }
  return paths
}

